#include "tigersheets/pivot_conversion.hpp"
#include "tigersheets/calculation.hpp"
#include "tigersheets/pivot_ownership.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Json source(){return {{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",Json::array({
 {{"row",1},{"col",1},{"input","Region"}},{{"row",1},{"col",2},{"input","Revenue"}},
 {{"row",2},{"col",1},{"input","East"}},{{"row",2},{"col",2},{"input","10"}},
 {{"row",3},{"col",1},{"input","West"}},{{"row",3},{"col",2},{"input","=20"}},
 {{"row",4},{"col",1},{"input","East"}},{{"row",4},{"col",2},{"input","30"}}})}},
 {{"id","l"},{"name","Old Summary"},{"cells",Json::array({{{"row",1},{"col",1},{"input","'Region"},{"style",{{"bold",true}}}},{{"row",1},{"col",2},{"input","'sum of Revenue"}},{{"row",2},{"col",1},{"input","'East"}},{{"row",2},{"col",2},{"input","40"}},{{"row",3},{"col",1},{"input","'West"}},{{"row",3},{"col",2},{"input","20"}},{{"row",4},{"col",1},{"input","'Grand Total"}},{{"row",4},{"col",2},{"input","60"}}})}}})},
 {"pivots",Json::array({{{"id","legacy"},{"staticSummary",true},{"source",{{"sheet","s"},{"row1",1},{"col1",1},{"row2",4},{"col2",2}}},{"rowField","Region"},{"valueField","Revenue"},{"aggregate","sum"},{"output",{{"sheet","l"},{"row",1},{"col",1}}}}})}};}
Json conversion(const Json& book){return convertStaticPivotOperations(book,CalculationEngine().calculate(book),"legacy","native-sheet","Native Report","native-report","ConvertedRevenue");}
void explicitPreview(){WorkbookSession session(source());const auto before=session.snapshot();require(session.snapshotView().at("pivots")[0].at("staticSummary")==true,"loading a legacy summary does not implicitly convert it");const auto operations=conversion(before);require(operations.size()==3,"conversion is one add-sheet, metadata-removal and native-report transaction");std::string error;require(!session.preview(0,operations,&error).is_null(),error.c_str());require(session.snapshot()==before,"conversion preview leaves canonical legacy workbook unchanged");const auto preview=*session.previewView();require(preview.at("sheets").size()==3&&preview.at("pivots").size()==1&&preview.at("pivots")[0].at("version")==1,"conversion preview creates one native report on a new worksheet");require(preview.at("sheets")[1]==before.at("sheets")[1],"conversion preserves every old static summary input and style");require(preview.at("pivots")[0].at("layout").at("grandTotals")[0].at("value")==60,"converted native report uses current calculated source values");session.discard();require(session.snapshot()==before&&!session.canUndo(),"discarded conversion has no persistent effects");require(!session.preview(0,operations,&error).is_null()&&session.accept(&error),error.c_str());require(session.snapshotView().at("sheets").size()==3&&session.snapshotView().at("pivots")[0].at("id")=="native-report","accept publishes conversion atomically");require(session.undo()&&session.snapshotView().at("sheets").size()==2&&session.snapshotView().at("pivots")[0].at("staticSummary")==true,"one undo removes the new native report and restores legacy metadata");require(session.snapshotView().at("sheets")[1]==before.at("sheets")[1],"undo preserves old static values");}
Json withOwned(){auto book=source();book["sheets"].push_back({{"id","owned"},{"name","Existing Native"},{"cells",Json::array()}});const Json definition={{"id","existing"},{"name","ExistingRevenue"},{"source",book["pivots"][0]["source"]},{"rows",Json::array({{{"field","Region"}}})},{"columns",Json::array()},{"filters",Json::array()},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"},{"name","Revenue"}}})},{"output",{{"sheet","owned"},{"row1",1},{"col1",1}}}};const auto generated=generatePivot(book,CalculationEngine().calculate(book),definition);applyPivotTransaction(book,pivotOperations(book,generated)[0]);return book;}
void preservesNativeOwnership(){const auto book=withOwned();WorkbookSession session(book);std::string error;const auto result=session.preview(0,conversion(book),&error);require(!result.is_null(),"explicit legacy conversion must coexist with unchanged native reports");const auto preview=*session.previewView();require(preview.at("pivots").size()==2&&preview.at("pivots")[0]==book.at("pivots")[1],"conversion preserves existing native metadata exactly");require(preview.at("sheets")[2]==book.at("sheets")[2],"conversion preserves existing native owned output");session.discard();
 for(const auto* mode:{"delete","change","add"}){auto definitions=book.at("pivots");if(std::string(mode)=="delete")definitions.erase(definitions.begin()+1);else if(std::string(mode)=="change")definitions[1]["name"]="Changed";else{auto duplicate=definitions[1];duplicate["id"]="injected";duplicate["name"]="Injected";definitions.push_back(duplicate);}require(!session.apply(0,Json::array({{{"type","set_metadata"},{"key","pivots"},{"value",definitions}}}),&error)&&session.snapshot()==book,"generic metadata cannot delete, mutate or inject native report definitions");}
}
void lightweightDefinition(){const auto book=source();const auto definition=staticPivotConversionDefinition(book,"legacy","new-sheet","new-pivot","NewRevenue");require(definition.at("source")==book.at("pivots")[0].at("source")&&definition.at("output")==Json({{"sheet","new-sheet"},{"row1",1},{"col1",1}}),"lightweight conversion definition uses stored source and fresh output");require(!definition.contains("cache")&&!definition.contains("layout")&&definition.at("rows")[0].at("field")=="Region"&&definition.at("values")[0].at("aggregate")=="sum","lightweight conversion returns only requested native fields");
 for(const auto* mode:{"unknown","not-static","native","aggregate","source-fraction","source-overflow","output","missing-field"}){auto malformed=book;auto& legacy=malformed["pivots"][0];const std::string kind=mode;if(kind=="unknown")legacy["calculatedFields"]=Json::array();if(kind=="not-static")legacy["staticSummary"]=false;if(kind=="native")legacy["version"]=1;if(kind=="aggregate")legacy["aggregate"]="median";if(kind=="source-fraction")legacy["source"]["row2"]=4.5;if(kind=="source-overflow")legacy["source"]["row2"]=4294967300ULL;if(kind=="output")legacy["output"]["row"]=0;if(kind=="missing-field")legacy.erase("rowField");bool rejected=false;try{staticPivotConversionDefinition(malformed,"legacy","new-sheet","new-pivot","NewRevenue");}catch(const std::exception&){rejected=true;}require(rejected,"unsupported or malformed legacy metadata cannot be converted");require(malformed.at("sheets")==book.at("sheets"),"refused conversion never mutates summary cells");}
}
void refusalAndAggregates(){
 for(const auto& [aggregate,answer]:std::vector<std::pair<std::string,double>>{{"sum",60},{"count",3},{"average",20},{"min",10},{"max",30}}){auto book=source();book["pivots"][0]["aggregate"]=aggregate;const auto operations=conversion(book);require(operations[2].at("definition").at("layout").at("grandTotals")[0].at("value")==answer,"all five supported legacy aggregates convert from current source");WorkbookSession session(book);require(session.apply(0,operations)&&session.snapshotView().at("sheets")[1]==book.at("sheets")[1],"aggregate conversion leaves old static summary cells unchanged");}
 for(const auto* mode:{"stale","error","missing-field","identity","name","cancel","native-source"}){auto book=std::string(mode)=="native-source"?withOwned():source();if(std::string(mode)=="error")book["sheets"][0]["cells"][5]["input"]="=1/0";if(std::string(mode)=="missing-field")book["pivots"][0]["rowField"]="Absent";if(std::string(mode)=="native-source")book["pivots"][0]["source"]={{"sheet","owned"},{"row1",1},{"col1",1},{"row2",3},{"col2",2}};const auto before=book;auto calculated=CalculationEngine().calculate(book);if(std::string(mode)=="stale")calculated["revision"]=99;bool rejected=false;try{convertStaticPivotOperations(book,calculated,"legacy",std::string(mode)=="identity"?"s":"new-sheet",std::string(mode)=="name"?"source":"New Sheet","new-pivot","ConvertedRevenue",0,[&]{return std::string(mode)=="cancel";});}catch(const std::exception&){rejected=true;}require(rejected&&book==before,"invalid, stale, error, cancelled or native-owned sources cannot be converted");}
}
int main(){try{explicitPreview();preservesNativeOwnership();lightweightDefinition();refusalAndAggregates();std::cout<<"pivot conversion tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
